[CmdletBinding()]
param(
  [Parameter(Mandatory)][string]$PlanPath,
  [Parameter(Mandatory)][string]$ObserverReceiptPath,
  [Parameter(Mandatory)][string]$OuterReceiptPath,
  [Parameter(Mandatory)][string]$ObserverSourcePath,
  [Parameter(Mandatory)][ValidatePattern('^[0-9a-fA-F]{64}$')][string]$ObserverSourceSha256,
  [Parameter(Mandatory)][string]$OutputPath
)
$ErrorActionPreference='Stop'
function Require([bool]$Condition,[string]$Message){if(-not $Condition){throw $Message}}
function Read-BoundedJson([string]$Path,[int64]$Limit=2097152){$item=Get-Item -LiteralPath $Path -Force -ErrorAction Stop;Require (-not $item.PSIsContainer -and ($item.Attributes -band [IO.FileAttributes]::ReparsePoint)-eq 0) "non-regular receipt: $Path";Require ($item.Length -le $Limit) "receipt exceeds bound: $Path";return [IO.File]::ReadAllText($item.FullName,(New-Object Text.UTF8Encoding($false)))|ConvertFrom-Json}
function Full([string]$Path){return [IO.Path]::GetFullPath($Path)}
function Same([string]$Left,[string]$Right){return (Full $Left).Equals((Full $Right),[StringComparison]::OrdinalIgnoreCase)}
function File-Proof([string]$Path,[int64]$MaxBytes=67108864,[int64]$ExpectedBytes=-1,[string]$ExpectedSha='',[string]$Label='file'){$item=Get-Item -LiteralPath $Path -Force -ErrorAction Stop;Require (-not $item.PSIsContainer -and ($item.Attributes -band [IO.FileAttributes]::ReparsePoint)-eq 0) "$Label regular-file proof failed";Require ($item.Length -le $MaxBytes) "$Label exceeds bound";if($ExpectedBytes -ge 0){Require ($item.Length -eq $ExpectedBytes) "$Label byte join mismatch"};$sha=(Get-FileHash -LiteralPath $item.FullName -Algorithm SHA256).Hash.ToLowerInvariant();if($ExpectedSha){Require ($sha -ceq $ExpectedSha.ToLowerInvariant()) "$Label hash join mismatch"};return [ordered]@{path=$item.FullName;bytes=$item.Length;sha256=$sha}}
function Receipt-Stream([object]$Receipt,[string]$PathField,[string]$BytesField,[string]$ShaField,[string]$Label){$path=[string]$Receipt.$PathField;Require $path "$Label path missing";Require ([int64]$Receipt.$BytesField -ge 0) "$Label byte receipt missing";Require ([string]$Receipt.$ShaField -match '^[0-9a-fA-F]{64}$') "$Label hash receipt missing";return File-Proof $path 8388608 ([int64]$Receipt.$BytesField) ([string]$Receipt.$ShaField) $Label}
function Write-AtomicFresh([string]$Path,[object]$Value){Require (-not(Test-Path -LiteralPath $Path)) "archive verifier output must be fresh: $Path";$parent=Split-Path -Parent (Full $Path);if(-not(Test-Path -LiteralPath $parent)){[IO.Directory]::CreateDirectory($parent)|Out-Null};$tmp="$Path.$PID.$([guid]::NewGuid().ToString('N')).tmp";$bytes=[Text.Encoding]::UTF8.GetBytes(($Value|ConvertTo-Json -Depth 16)+"`r`n");$stream=[IO.File]::Open($tmp,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);try{$stream.Write($bytes,0,$bytes.Length);$stream.Flush($true)}finally{$stream.Dispose()};[IO.File]::Move($tmp,$Path)}
$errors=New-Object 'System.Collections.Generic.List[string]';$status='held';$files=New-Object 'System.Collections.Generic.List[object]';$plan=$null;$observer=$null;$outer=$null;$manifest=$null;$launcher=$null;$collector=$null;$coordinator=$null
try{
  $outer=Read-BoundedJson (Full $OuterReceiptPath)
  $plan=Read-BoundedJson (Full $PlanPath);Require ([string]$plan.schema -eq 'sr0-display-selfjob-v4-fresh-one-run') 'plan schema mismatch';Require ([int]$plan.runs -eq 1 -and [int]$plan.deadlineSeconds -eq 900 -and [int]$plan.pollSeconds -eq 1) 'plan run contract mismatch';Require ([string]$plan.memoryLimitFlags -ceq '0x200' -and [int64]$plan.aggregateJobMemoryLimitBytes -eq 1073741824) 'plan memory contract mismatch';Require ([bool]$plan.noActivate -and [bool]$plan.noResources -and -not [bool]$plan.killOnJobClose) 'plan interaction contract mismatch';Require ([string]$plan.taskName -ceq [string]$plan.tag) 'plan task/tag mismatch'
  $observer=Read-BoundedJson (Full $ObserverReceiptPath);Require ([string]$observer.kind -eq 'sr0-display-selfjob-v4-fresh-observer-r2') 'observer kind mismatch';Require ([string]$observer.status -eq 'passed') 'observer is not passed';Require (Same ([string]$observer.planPath) $PlanPath) 'observer plan join mismatch';Require ([bool]$observer.overallWithinDeadline -and [bool]$observer.scheduleStreamsSealed -and [bool]$observer.scheduleExitIdentity -and [int64]$observer.scheduleExit -eq 0) 'observer schedule proof incomplete';Require ([bool]$observer.workerOriginalHandleAcquired -and [bool]$observer.workerKernelTerminal -and [bool]$observer.workerExitIdentity -and [int64]$observer.workerExitDotnet -eq 0 -and [bool]$observer.workerSessionMatch) 'observer worker proof incomplete';Require ([int64]$observer.transportFinalActive -eq 1 -and [int64]$observer.transportFinalLimitBytes -eq 268435456 -and [int64]$observer.transportFinalLimitFlags -eq 512) 'observer transport proof incomplete';$files.Add((Receipt-Stream $observer 'scheduleStdoutPath' 'scheduleStdoutBytes' 'scheduleStdoutSha256' 'observer schedule stdout'));$files.Add((Receipt-Stream $observer 'scheduleStderrPath' 'scheduleStderrBytes' 'scheduleStderrSha256' 'observer schedule stderr'))
  $sourceProof=File-Proof (Full $ObserverSourcePath) 2097152 -1 $ObserverSourceSha256 'observer source';Require (Same ([string]$outer.scriptPath) $ObserverSourcePath) 'outer script/source join mismatch';Require ([string]$outer.scriptSha256 -ceq $ObserverSourceSha256.ToLowerInvariant()) 'outer script hash/source join mismatch'
  $outer=Read-BoundedJson (Full $OuterReceiptPath);Require ([string]$outer.kind -eq 'sr0-root-transport-job-v1' -and [string]$outer.status -eq 'passed') 'outer transport not passed';Require ([bool]$outer.childHandleAcquired -and [bool]$outer.childTerminal -and [bool]$outer.childExitIdentity -and [int64]$outer.childExit -eq 0 -and [bool]$outer.streamsSealed -and -not [bool]$outer.outputCapExceeded -and -not [bool]$outer.memoryCapExceeded) 'outer transport proof incomplete';Require ([int64]$outer.activeAfter -eq 1 -and [int64]$outer.budgetBytes -eq 268435456) 'outer transport self-only proof incomplete';$files.Add((Receipt-Stream $outer 'stdoutPath' 'stdoutBytes' 'stdoutSha256' 'outer stdout'));$files.Add((Receipt-Stream $outer 'stderrPath' 'stderrBytes' 'stderrSha256' 'outer stderr'))
  $runRoot=Full ([string]$plan.runRoot);Require (Test-Path -LiteralPath $runRoot -PathType Container) 'run root missing';$manifestPath=Full ([string]$plan.manifestPath);$manifest=Read-BoundedJson $manifestPath;Require ([string]$manifest.schema -eq 'sr0-display-selfjob-v4-one-shot' -and [string]$manifest.taskName -ceq [string]$plan.taskName -and [string]$manifest.tag -ceq [string]$plan.tag) 'manifest identity mismatch';Require (Same ([string]$manifest.runRoot) $runRoot -and [int64]$manifest.aggregateJobMemoryLimitBytes -eq 1073741824 -and [int]$manifest.deadlineSeconds -eq 900 -and [int]$manifest.pollSeconds -eq 1) 'manifest run contract mismatch';Require ([bool]$manifest.noActivate -and [bool]$manifest.noResources) 'manifest interaction contract mismatch'
  foreach($pair in @(@('frozenTask','frozenTaskPath','frozenTaskSha256'),@('helper','helperPath','helperSha256'),@('parser','parserPath','parserSha256'),@('worker','workerPath','workerSha256'),@('launcherHelper','launcherHelperPath','launcherHelperSha256'),@('collector','collectorPath','collectorSha256'),@('coordinator','coordinatorPath','coordinatorSha256'),@('wrapper','wrapperPath','wrapperSha256'),@('workloadExe','workloadExe','workloadExeSha256'),@('rendererDll','rendererDll','rendererDllSha256'),@('presentMonExe','presentMonExe','presentMonSha256'))){$p=$plan.sources.([string]$pair[0]);Require ($null -ne $p) "plan source missing: $($pair[0])";Require (Same ([string]$manifest.([string]$pair[1])) ([string]$p.path)) "manifest path join mismatch: $($pair[0])";Require ([string]$manifest.([string]$pair[2]) -ceq ([string]$p.sha256).ToLowerInvariant()) "manifest hash join mismatch: $($pair[0])"}
  $launcherPath=Full ([string]$observer.launcherReceiptPath);Require (Same $launcherPath (Join-Path $runRoot 'launcher-receipt.json')) 'launcher receipt path join mismatch';$launcher=Read-BoundedJson $launcherPath;Require ([string]$launcher.kind -eq 'sr0-display-launcher-v4' -and [string]$launcher.status -eq 'passed' -and [string]$launcher.taskName -ceq [string]$plan.taskName) 'launcher receipt incomplete';Require ([int64]$launcher.aggregateActiveAfter -eq 1 -and [bool]$launcher.aggregateDescendantsQuiesced -and -not [bool]$launcher.aggregateMemoryCapExceeded -and [bool]$launcher.coordinatorHandleAcquired -and [bool]$launcher.coordinatorTerminal -and [bool]$launcher.coordinatorExitIdentity -and [int64]$launcher.coordinatorExit -eq 0 -and [bool]$launcher.collectorHandleAcquired -and [bool]$launcher.collectorTerminal -and [bool]$launcher.collectorExitIdentity -and [int64]$launcher.collectorExit -eq 0) 'launcher cleanup/exit proof incomplete'
  $collector=Read-BoundedJson ([string]$manifest.memoryReceiptPath);Require ([string]$collector.kind -eq 'sr0-display-collector-v4' -and [string]$collector.status -eq 'completed' -and [string]$collector.taskName -ceq [string]$plan.taskName) 'collector qualification not completed';Require ([bool]$collector.parentOriginalHandleRetained -and [bool]$collector.sessionMatch -and [bool]$collector.presentMonStarted -and [bool]$collector.presentMonTerminal -and [bool]$collector.presentMonExitIdentity -and [int64]$collector.presentMonExit -eq 0 -and [bool]$collector.presentMonSessionAbsent -and [bool]$collector.workloadTerminal -and [bool]$collector.workloadExitIdentity -and [int64]$collector.workloadExit -eq 0) 'collector terminal proof incomplete';Require ([bool]$collector.activeReadableAfter -and [int64]$collector.activeAfter -eq 1 -and [bool]$collector.activeSelfOnly -and [bool]$collector.releaseAllowed -and [bool]$collector.lockReleased -and -not [bool]$collector.outputExceeded -and -not [bool]$collector.timedOut -and $null -eq $collector.failure) 'collector ownership/cleanup proof incomplete';Require ($collector.workloadProof -and [bool]$collector.workloadProof.ownershipTerminal -and [bool]$collector.workloadProof.qualificationPass) 'collector workload qualification proof incomplete';Require ([int64]$collector.jobMemoryLimitBytes -eq 1073741824 -and [int64]$collector.limitFlagsAfter -eq 512 -and [int64]$collector.peakJobMemoryAfterBytes -le 1073741824) 'collector memory proof incomplete'
  $coordinator=Read-BoundedJson ([string]$manifest.coordinatorOutputPath);Require ([string]$coordinator.kind -eq 'sr0-display-coordinator-v4' -and [string]$coordinator.status -eq 'passed' -and [string]$coordinator.taskName -ceq [string]$plan.taskName) 'coordinator proof not passed';Require ([bool]$coordinator.parentCertificatePresent -and [bool]$coordinator.parentKernelTerminal -and [int64]$coordinator.parentExitSigned -eq 0 -and [int64]$coordinator.parentExitDotnet -eq 0 -and [bool]$coordinator.lockOwnerObserved -and @($coordinator.errors).Count -eq 0) 'coordinator parent/lock proof incomplete'
  $result=File-Proof ([string]$manifest.resultFile) 2097152 -1 '' 'workload result';$files.Add($result);$csv=File-Proof ([string]$collector.presentMonCsv) 67108864 -1 '' 'PresentMon CSV';$files.Add($csv);$status='passed'
}catch{[void]$errors.Add(([string]$_.Exception.Message).Substring(0,[Math]::Min(1024,([string]$_.Exception.Message).Length)))}
$report=[ordered]@{kind='sr0-display-selfjob-v4-fresh-one-run-archive-v1';status=$status;qualification='strict-displayed-workload-and-process';planPath=Full $PlanPath;observerReceiptPath=Full $ObserverReceiptPath;outerReceiptPath=Full $OuterReceiptPath;manifestPath=if($manifest){Full ([string]$plan.manifestPath)}else{$null};runRoot=if($plan){Full ([string]$plan.runRoot)}else{$null};observerSource=$sourceProof;files=@($files);errors=@($errors);checkedAt=[DateTimeOffset]::UtcNow.ToString('o')};Write-AtomicFresh $OutputPath $report;$report|ConvertTo-Json -Depth 16;if($status -eq 'passed'){exit 0}else{exit 1}
